// Exercise multiple overloads of Plist::readPlist using in-memory buffers, streams, and files.
// Generate a random buffer; FUZZ_PARAM_STR() guarantees size in [1, 4096].
std::string buf = FUZZ_PARAM_STR();
const char* bytes = buf.data();
int64_t size = static_cast<int64_t>(buf.size());

// Overload: void readPlist(const char* byteArrayTemp, int64_t size, boost::any& message)
try {
    boost::any any_root;
    Plist::readPlist(bytes, size, any_root);
    // If parsing succeeded, any_root should contain a plist-compatible type.
} catch (const Plist::Error&) {
    // Valid error path for malformed input.
} catch (...) {
    FUZZ_BAIL();
}

// Overload: void readPlist(std::istream& stream, boost::any& message)
try {
    std::stringstream ss;
    ss.write(bytes, static_cast<std::streamsize>(size));
    ss.seekg(0);
    boost::any any_root2;
    Plist::readPlist(ss, any_root2);
} catch (const Plist::Error&) {
} catch (...) {
    FUZZ_BAIL();
}

