int month  = static_cast<int>(*FUZZ_PARAM(unsigned int) % 12) + 1;   // 1-12
int day    = static_cast<int>(*FUZZ_PARAM(unsigned int) % 28) + 1;   // 1-28
int year   = 1970 + static_cast<int>(*FUZZ_PARAM(unsigned int) % 200);
int hour   = static_cast<int>(*FUZZ_PARAM(unsigned int) % 24);
int minute = static_cast<int>(*FUZZ_PARAM(unsigned int) % 60);
int second = static_cast<int>(*FUZZ_PARAM(unsigned int) % 60);
bool utc   = ((*FUZZ_PARAM(unsigned int) % 2) != 0);
// Invoke setter; API does not specify exceptions here.
date->set(month, day, year, hour, minute, second, utc);
// Return the same object back to the pool.

// Set to current system time; no extra constraints.
date->setToCurrentTime();
// Object remains valid and is returned.

