Plist::Date start;
start.set(1, 1, 2001, 0, 0, 0, true);
// Compute difference; result may be negative depending on ordering.
(void)date->secondsSinceDate(start);
// Return the original date object.

// Create two dates and compare them; assert basic comparator properties.
Plist::Date a; a.set(1, 1, 2000, 0, 0, 0, true);
Plist::Date b; b.set(1, 1, 2000, 0, 0, 0, true);
int r_eq = Plist::Date::compare(a, b);
FUZZ_ASSERT(r_eq == 0, "compare equal dates should return 0");
// Make b later than a and compare again.
