bool gt_eq = ((*date) > rhs);          // should be false
(void)gt_eq;
// Make rhs earlier to trigger true path.
rhs.set(1, 1, 1970, 0, 0, 0, true);
bool gt_true = ((*date) > rhs);
(void)gt_true;
// Return date unchanged.

