// Apple epoch seconds; constrain to a reasonable finite range to avoid NaN/Inf.
double raw = *FUZZ_PARAM(double);
if (!(raw == raw)) raw = 0.0; // sanitize NaN to 0
// Clamp to roughly +/- 200 years around 2001 in seconds.
const double LIMIT = 200.0 * 365.25 * 24.0 * 3600.0;
if (raw >  LIMIT) raw =  LIMIT;
if (raw < -LIMIT) raw = -LIMIT;
date->setTimeFromAppleEpoch(raw);
