import random
import struct
import datetime
from typing import List, Tuple

# This generator produces valid Apple plist documents, either XML or binary, with
# varied root types to exercise different code paths in Plist::readPlist.
# - XML plists conform roughly to Apple plist 1.0 DTD.
# - Binary plists follow bplist00 spec minimally for common scalar/container types.
# The size is kept <= 4096 bytes.

# ------------------------------
# XML PLIST GENERATION
# ------------------------------

def _xml_header() -> str:
    return (
        "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n"
        "<!DOCTYPE plist PUBLIC \"-//Apple//DTD PLIST 1.0//EN\" \"http://www.apple.com/DTDs/PropertyList-1.0.dtd\">\n"
    )


def _xml_wrap(root: str) -> bytes:
    doc = _xml_header() + "<plist version=\"1.0\">" + root + "</plist>\n"
    return doc.encode("utf-8")


def _xml_escape(s: str) -> str:
    return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")


def _rand_ascii(rng: random.Random, min_len: int, max_len: int) -> str:
    length = rng.randint(min_len, max_len)
    alphabet = (
        "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 "
        "_-.:/@#%+?=,"  # include URL-ish and punctuation
    )
    return "".join(rng.choice(alphabet) for _ in range(length))


def _xml_bool(rng: random.Random) -> bytes:
    return _xml_wrap("<true/>" if rng.choice([True, False]) else "<false/>")


def _xml_int(rng: random.Random) -> bytes:
    # 64-bit signed range variety
    choices = [0, 1, -1, 2**31 - 1, -2**31, 2**63 - 1, -2**63]
    if rng.random() < 0.6:
        v = rng.choice(choices)
    else:
        v = rng.randint(-2**63, 2**63 - 1)
    return _xml_wrap(f"<integer>{v}</integer>")


def _xml_real(rng: random.Random) -> bytes:
    # Use finite decimals to avoid NaN/Inf handling ambiguity
    choices = [0.0, 1.0, -1.0, 3.14159, -1234.5, 1e-3, 1.2e6]
    v = rng.choice(choices) if rng.random() < 0.7 else (rng.random() - 0.5) * 1e9
    # Format with either fixed or scientific
    if rng.random() < 0.5:
        s = f"{v:.6f}"
    else:
        s = f"{v:.6g}"
    return _xml_wrap(f"<real>{s}</real>")


def _xml_string(rng: random.Random) -> bytes:
    s = _rand_ascii(rng, 0, 64)
    return _xml_wrap(f"<string>{_xml_escape(s)}</string>")


def _xml_data(rng: random.Random) -> bytes:
    # Base64 of random bytes
    n = rng.randint(0, 64)
    raw = bytes(rng.getrandbits(8) for _ in range(n))
    import base64
    b64 = base64.b64encode(raw).decode("ascii")
    return _xml_wrap(f"<data>{b64}</data>")


def _xml_date(rng: random.Random) -> bytes:
    # ISO 8601 Zulu format: YYYY-MM-DDTHH:MM:SSZ
    # Choose near-epoch, 2001 epoch, and random recent times.
    candidates: List[datetime.datetime] = [
        datetime.datetime(1970, 1, 1, 0, 0, 0),
        datetime.datetime(2001, 1, 1, 0, 0, 0),
        datetime.datetime(2010, 6, 1, 12, 30, 15),
    ]
    if rng.random() < 0.6:
        dt = rng.choice(candidates)
    else:
        # random date 1970..2038
        year = rng.randint(1970, 2038)
        month = rng.randint(1, 12)
        # choose a valid day for the month
        day_limit = [31, 29 if year % 4 == 0 and (year % 100 != 0 or year % 400 == 0) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1]
        day = rng.randint(1, day_limit)
        hour = rng.randint(0, 23)
        minute = rng.randint(0, 59)
        second = rng.randint(0, 59)
        dt = datetime.datetime(year, month, day, hour, minute, second)
    s = dt.strftime("%Y-%m-%dT%H:%M:%SZ")
    return _xml_wrap(f"<date>{s}</date>")


def _xml_array(rng: random.Random, depth: int = 0) -> bytes:
    # Array of mixed simple elements
    n = rng.randint(0, 8)
    elems: List[bytes] = []
    for _ in range(n):
        elems.append(_xml_value(rng, depth + 1))
    inner = b"".join(elems).decode("utf-8")
    return _xml_wrap(f"<array>{inner}</array>")


def _xml_dict(rng: random.Random, depth: int = 0) -> bytes:
    n = rng.randint(0, 8)
    items: List[str] = []
    for _ in range(n):
        key = _xml_escape(_rand_ascii(rng, 1, 16))
        val = _xml_value(rng, depth + 1).decode("utf-8")
        items.append(f"<key>{key}</key>{val}")
    inner = "".join(items)
    return _xml_wrap(f"<dict>{inner}</dict>")


def _xml_value(rng: random.Random, depth: int = 0) -> bytes:
    # Limit nesting to keep size bounded
    choices = [
        _xml_bool,
        _xml_int,
        _xml_real,
        _xml_string,
        _xml_data,
        _xml_date,
    ]
    if depth < 2:
        choices.extend([_xml_array, _xml_dict])
    gen = rng.choice(choices)
    return gen(rng)


def _generate_xml(rng: random.Random) -> bytes:
    # Bias towards dict/array roots since stubs any-cast to containers
    root_generators = [_xml_dict, _xml_array, _xml_string, _xml_int, _xml_real, _xml_bool, _xml_date, _xml_data]
    weights = [0.35, 0.25, 0.1, 0.08, 0.08, 0.06, 0.04, 0.04]
    gen = rng.choices(root_generators, weights=weights, k=1)[0]
    return gen(rng)

# ------------------------------
# BINARY PLIST GENERATION (bplist00)
# Minimal encoder supporting a subset: null, bool, int, real, date, data, string, ascii, array, dict.
# ------------------------------

class _BPWriter:
    def __init__(self):
        self.objects: List[bytes] = []
        self.obj_index: dict[int, int] = {}

    def _encode_int(self, v: int) -> bytes:
        # choose minimal width 1,2,4,8 bytes signed
        if -(1<<7) <= v <= (1<<7)-1:
            n = 1
        elif -(1<<15) <= v <= (1<<15)-1:
            n = 2
        elif -(1<<31) <= v <= (1<<31)-1:
            n = 4
        else:
            n = 8
        marker = 0x10 | {1:0,2:1,4:2,8:3}[n]
        if n == 1:
            return bytes([marker]) + struct.pack(">b", v)
        if n == 2:
            return bytes([marker]) + struct.pack(">h", v)
        if n == 4:
            return bytes([marker]) + struct.pack(">i", v)
        return bytes([marker]) + struct.pack(">q", v)

    def _encode_real(self, v: float) -> bytes:
        # always 8-byte float
        return bytes([0x23]) + struct.pack(">d", float(v))

    def _encode_bool(self, b: bool) -> bytes:
        return bytes([0x09 if b else 0x08])

    def _encode_null(self) -> bytes:
        return bytes([0x00])

    def _encode_date(self, seconds_since_2001: float) -> bytes:
        # 0x33 + float64 seconds since 2001-01-01
        return bytes([0x33]) + struct.pack(">d", float(seconds_since_2001))

    def _count_and_size(self, count: int) -> bytes:
        if count < 15:
            return bytes()
        # 0x10|n, n is int power-of-two exponent; we store count as int object following marker 0x1? per spec
        # But for container count >= 15, the count is stored as an integer object immediately following marker nibble 0xF
        # We'll encode count as minimal int object and append here for convenience.
        return self._encode_int(count)

    def _marker_with_count(self, base: int, count: int) -> bytes:
        if count < 15:
            return bytes([base | count])
        else:
            return bytes([base | 0x0F])

    def _encode_ascii(self, s: str) -> bytes:
        raw = s.encode('ascii', 'ignore')
        m = self._marker_with_count(0x50, len(raw))
        ext = self._count_and_size(len(raw))
        return m + ext + raw

    def _encode_utf16(self, s: str) -> bytes:
        raw = s.encode('utf-16be')
        char_count = len(raw) // 2
        m = self._marker_with_count(0x60, char_count)
        ext = self._count_and_size(char_count)
        return m + ext + raw

    def _encode_string(self, s: str) -> bytes:
        try:
            s.encode('ascii')
            return self._encode_ascii(s)
        except Exception:
            return self._encode_utf16(s)

    def _encode_data(self, b: bytes) -> bytes:
        m = self._marker_with_count(0x40, len(b))
        ext = self._count_and_size(len(b))
        return m + ext + b

    def _encode_array(self, obj_refs: List[int], ref_size: int) -> bytes:
        count = len(obj_refs)
        m = self._marker_with_count(0xA0, count)
        ext = self._count_and_size(count)
        body = b"".join([obj_refs[i].to_bytes(ref_size, 'big') for i in range(count)])
        return m + ext + body

    def _encode_dict(self, key_refs: List[int], val_refs: List[int], ref_size: int) -> bytes:
        count = len(key_refs)
        m = self._marker_with_count(0xD0, count)
        ext = self._count_and_size(count)
        body = b"".join([key_refs[i].to_bytes(ref_size, 'big') for i in range(count)]) + \
               b"".join([val_refs[i].to_bytes(ref_size, 'big') for i in range(count)])
        return m + ext + body

    def add_object(self, obj: Tuple[str, object]):
        # returns index
        kind, val = obj
        if kind == 'null':
            data = self._encode_null()
        elif kind == 'bool':
            data = self._encode_bool(bool(val))
        elif kind == 'int':
            data = self._encode_int(int(val))
        elif kind == 'real':
            data = self._encode_real(float(val))
        elif kind == 'date':
            data = self._encode_date(float(val))
        elif kind == 'data':
            data = self._encode_data(bytes(val))
        elif kind == 'string':
            data = self._encode_string(str(val))
        else:
            raise ValueError('unknown simple kind')
        self.objects.append(data)
        return len(self.objects) - 1

    def add_array(self, refs: List[int], ref_size: int):
        data = self._encode_array(refs, ref_size)
        self.objects.append(data)
        return len(self.objects) - 1

    def add_dict(self, key_refs: List[int], val_refs: List[int], ref_size: int):
        data = self._encode_dict(key_refs, val_refs, ref_size)
        self.objects.append(data)
        return len(self.objects) - 1

    def build(self, top_object_index: int) -> bytes:
        # calculate ref size
        obj_count = len(self.objects)
        if obj_count <= 0xFF:
            ref_size = 1
        elif obj_count <= 0xFFFF:
            ref_size = 2
        elif obj_count <= 0xFFFFFFFF:
            ref_size = 4
        else:
            ref_size = 8
        # Rebuild containers with correct ref sizes is skipped for simplicity; we ensure to create containers only after we know ref_size.
        # So caller must create containers after simple objects or pass ref_size already.

        # Build object table
        table = b""
        offsets: List[int] = []
        offset = 0
        for obj in self.objects:
            offsets.append(offset)
            table += obj
            offset += len(obj)

        # trailer
        offset_size = 1 if max(offsets + [0]) <= 0xFF else 2 if max(offsets + [0]) <= 0xFFFF else 4 if max(offsets + [0]) <= 0xFFFFFFFF else 8
        trailer = bytearray(32)
        trailer[6] = offset_size
        trailer[7] = ref_size
        trailer[8:16] = struct.pack(">Q", len(self.objects))
        trailer[16:24] = struct.pack(">Q", top_object_index)
        offset_table_offset = 8 + len(table)
        trailer[24:32] = struct.pack(">Q", offset_table_offset)

        # offset table
        off_tbl = b"".join(o.to_bytes(offset_size, 'big') for o in offsets)

        return b"bplist00" + table + off_tbl + bytes(trailer)


def _apple_epoch_seconds(dt: datetime.datetime) -> float:
    # seconds since 2001-01-01 UTC
    base = datetime.datetime(2001, 1, 1, 0, 0, 0)
    delta = (dt - base).total_seconds()
    return float(delta)


def _generate_binary(rng: random.Random) -> bytes:
    w = _BPWriter()

    # Build some shared simple objects first
    simple_indices: List[int] = []
    # strings
    for _ in range(rng.randint(2, 5)):
        s = _rand_ascii(rng, 1, 16)
        simple_indices.append(w.add_object(('string', s)))
    # ints
    for _ in range(rng.randint(2, 4)):
        v = rng.randint(-2**31, 2**31 - 1)
        simple_indices.append(w.add_object(('int', v)))
    # reals
    for _ in range(rng.randint(1, 3)):
        v = (rng.random() - 0.5) * 1e6
        simple_indices.append(w.add_object(('real', v)))
    # bools
    simple_indices.append(w.add_object(('bool', True)))
    simple_indices.append(w.add_object(('bool', False)))
    # date
    dt = datetime.datetime(2001, 1, 1) + datetime.timedelta(seconds=rng.randint(-10**6, 10**6))
    simple_indices.append(w.add_object(('date', _apple_epoch_seconds(dt))))
    # data
    data_len = rng.randint(0, 32)
    data_bytes = bytes(rng.getrandbits(8) for _ in range(data_len))
    simple_indices.append(w.add_object(('data', data_bytes)))

    # Now compute ref size based on count so far to build containers
    obj_count = len(w.objects)
    if obj_count <= 0xFF:
        ref_size = 1
    elif obj_count <= 0xFFFF:
        ref_size = 2
    elif obj_count <= 0xFFFFFFFF:
        ref_size = 4
    else:
        ref_size = 8

    # Create an array container referencing a subset of objects
    arr_refs = rng.sample(simple_indices, k=rng.randint(0, min(6, len(simple_indices)))) if simple_indices else []
    arr_idx = w.add_array(arr_refs, ref_size)

    # Create a dict container mapping some string keys to random values
    # Ensure keys are strings by creating new string objects if needed
    key_indices: List[int] = []
    val_indices: List[int] = []
    pair_count = rng.randint(0, 6)
    for _ in range(pair_count):
        key = _rand_ascii(rng, 1, 12)
        key_indices.append(w.add_object(('string', key)))
        val_indices.append(rng.choice(simple_indices + [arr_idx]))
    dict_idx = w.add_dict(key_indices, val_indices, ref_size)

    # Choose root among dict, array, or scalar
    root_choice = rng.choices(['dict', 'array', 'scalar'], weights=[0.5, 0.3, 0.2], k=1)[0]
    if root_choice == 'dict':
        top = dict_idx
    elif root_choice == 'array':
        top = arr_idx
    else:
        top = rng.choice(simple_indices)

    return w.build(top)

