def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Choose XML or binary; provide decent spread
    if rng.random() < 0.55:
        data = _generate_xml(rng)
    else:
        data = _generate_binary(rng)
    # Ensure max size constraint
    if len(data) > 4096:
        # If too large, fall back to a small simple XML string plist
        rng2 = random.Random(seed ^ 0xA5A5)
        return _xml_string(rng2)
    return data
